vector<int> findOrder(int n, vector<vector<int>>& pr) {
    vector<vector<int>> g(n); vector<int> indeg(n, 0), out;
    for (auto& e : pr) { g[e[1]].push_back(e[0]); indeg[e[0]]++; }
    priority_queue<int, vector<int>, greater<int>> h; for (int i = 0; i < n; i++) if (!indeg[i]) h.push(i);
    while (!h.empty()) { int u = h.top(); h.pop(); out.push_back(u); for (int v : g[u]) if (--indeg[v] == 0) h.push(v); }
    if ((int)out.size() != n) out.clear();
    return out;
}
